if (settings.manualRunning) {
    Text(
        "How you answer a running decision. Only the way you choose is on the screen.",
        style = MaterialTheme.typography.bodySmall
    )
    Column(modifier = Modifier.selectableGroup()) {
        RadioRow(
            label = "Swipe with two fingers",
            description = "Up to run, down to stay. No buttons on the screen.",
            selected = !settings.runByButtons,
            onSelect = { services.update { it.copy(runByButtons = false) } }
        )
        RadioRow(
            label = "Buttons on the screen",
            description = "A Run button and a Stay button. No swiping.",
            selected = settings.runByButtons,
            onSelect = { services.update { it.copy(runByButtons = true) } }
        )
    }
}

// On a no-ball the byes are already inside extraRuns, which the no-ball branch above added to the total.
extras = extras.copy(
    byes = extras.byes + outcome.byes, legByes = extras.legByes + outcome.legByes,
    total = extras.total + (if (outcome.isNoBall) 0 else outcome.byes + outcome.legByes)
)

val split = when {
    outcome.byes > 0 -> " (1 extra, ${countOf(outcome.byes, "bye")})"
    outcome.legByes > 0 -> " (1 extra, ${countOf(outcome.legByes, "leg bye")})"
    outcome.runs > 0 -> " (${outcome.runs} off the bat, 1 extra)"
    else -> ""
}
